def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the bounding boxes of connected 3-colored objects. A 2 inside
    # such a box marks the center of a 3x3 patch; exterior 2 distractors stay.
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    nr, nc = rr + dr, cc + dc
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 3 and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            boxes.append((min(a for a, b in cells), max(a for a, b in cells),
                          min(b for a, b in cells), max(b for a, b in cells)))
    centers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == 2 and any(r0 <= r <= r1 and c0 <= c <= c1
                                          for r0, r1, c0, c1 in boxes)]
    out = [row[:] for row in grid]
    for r, c in centers:
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and out[rr][cc] != 2:
                    out[rr][cc] = 1
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
